from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == background:
                continue
            neighbors = [grid[nr][nc] for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0 <= nr < h and 0 <= nc < w]
            if all(x != v for x in neighbors):
                other = [x for x in neighbors if x != v]
                if other:
                    common, n = Counter(other).most_common(1)[0]
                    out[r][c] = common if n > len(other) / 2 else background
                else:
                    out[r][c] = background
    return out
